import { NextResponse } from 'next/server';

export const runtime = 'edge';

// Mock DB. For Cloudflare Pages, use D1 or KV.
let items = [
  { name: 'Premium Plan', price: 10000, description: 'Monthly premium access.' }
];

export async function GET() {
  return NextResponse.json(items);
}

export async function POST(request) {
  try {
    const body = await request.json();
    const { name, price, description } = body;
    
    if (!name || !price) {
      return NextResponse.json({ success: false, message: 'Name and price required' }, { status: 400 });
    }
    
    items.push({ name, price, description });
    return NextResponse.json({ success: true, item: { name, price, description } });
  } catch (error) {
    return NextResponse.json({ success: false, message: 'Invalid data' }, { status: 400 });
  }
}
